PatternLayout.Pattern:
%n== event ======================================================%n
  date             %d{yyyy-MM-dd HH:mm:ss.SSS}
  date(ISO8601)    %d{ISO8601}
  date(UNIX)       %d{UNIX_MILLIS}
  date(tz+locale)  %d{EEEE dd MMMM yyyy}{UTC}{de-DE}
  relative         %r ms since JVM start
  level            %p / %-5level / %highlight{%level}
  logger           %c
  logger{36}       %c{36}
  logger{1.}       %c{1.}
  class            %C
  method           %M
  file:line        %F:%L
  location         %l
  fqcn             %fqcn
  thread           %t (id %T, priority %tp)
  processId        %pid{-}
  sequenceNumber   %sn
  nanoTime         %N
  uuid(time)       %u{TIME}
  uuid(random)     %u{RANDOM}
  marker           %marker
  markerSimple     %markerSimpleName
  endOfBatch       %endOfBatch
  MDC(all)         %X
  MDC(traceId)     %X{traceId}
  NDC              %x
  map              %K{event}
  traceId (otel)   %traceId
  spanId  (otel)   %spanId
  traceFlags       %traceFlags
  message          %m
  message(nolook)  %m{nolookups}
  --- transforms ---
  encode(HTML)     %encode{%m}{HTML}
  encode(JSON)     %encode{%m}{JSON}
  maxLength(24)    %maxLen{%m}{24}
  replace          %replace{%m}{\s+}{_}
  repeat           %repeat{=}{20}
  notEmpty         %notEmpty{[%marker] }
  equals           %equals{%level}{INFO}{<-- it was INFO>}
  equalsIgnoreCase           %equalsIgnoreCase{%level}{info}{<-- matched ignoring case>}
  style            %style{styled text}{bold,magenta}
  --- throwable ---
  throwable        %throwable{short}
  extended         %xEx{3}
  rootFirst        %rEx{3}
== end ========================================================
